// Dialog: React Aria (modal with trapped focus, Esc closes, focus returns to the trigger). Generated by shadcn and trimmed.
// Two ways in: inside a DialogTrigger (ConfirmButton), or controlled with isOpen (opened from a Menu item).
import { t } from "@zero/i18n"
import type { ReactNode } from "react"
import { Dialog as DialogPrimitive, DialogTrigger, Heading, Modal, ModalOverlay } from "react-aria-components"
import { Button, type ButtonProps } from "./button"

const overlay =
  "fixed inset-0 z-50 flex items-center justify-center bg-overlay p-4 data-entering:animate-in data-entering:fade-in-0 data-exiting:animate-out data-exiting:fade-out-0 motion-reduce:animate-none"
const sheet = "w-full max-w-sm rounded-sheet border border-strong bg-raised p-5 text-fg outline-none data-entering:animate-in data-entering:zoom-in-95 motion-reduce:animate-none"

type Body = (close: () => void) => ReactNode

function Content({ title, children }: { title: string; children: Body }) {
  return (
    <DialogPrimitive className="flex flex-col gap-4 outline-none">
      {({ close }) => (
        <>
          <Heading slot="title" className="text-lg font-semibold">
            {title}
          </Heading>
          {children(close)}
        </>
      )}
    </DialogPrimitive>
  )
}

export function Dialog({ title, children, isOpen, onOpenChange }: { title: string; children: Body; isOpen?: boolean; onOpenChange?: (open: boolean) => void }) {
  return (
    <ModalOverlay isDismissable className={overlay} {...(isOpen !== undefined && { isOpen })} {...(onOpenChange && { onOpenChange })}>
      <Modal className={sheet}>
        <Content title={title}>{children}</Content>
      </Modal>
    </ModalOverlay>
  )
}

// Cancel + the destructive action, for both entry points.
function ConfirmActions({ close, confirmLabel, onConfirm }: { close: () => void; confirmLabel: string; onConfirm: () => void }) {
  return (
    <div className="flex justify-end gap-2">
      <Button variant="ghost" onPress={close}>
        {t("common.cancel")}
      </Button>
      <Button
        variant="destructive"
        autoFocus
        onPress={() => {
          close()
          onConfirm()
        }}
      >
        {confirmLabel}
      </Button>
    </div>
  )
}

// Button that asks for confirmation before a destructive action (replaces window.confirm).
export function ConfirmButton({
  title,
  description,
  confirmLabel = t("common.delete"),
  onConfirm,
  ...button
}: Omit<ButtonProps, "onPress"> & { title: string; description?: ReactNode; confirmLabel?: string; onConfirm: () => void }) {
  return (
    <DialogTrigger>
      <Button {...button} />
      <Dialog title={title}>
        {(close) => (
          <>
            {description && <p className="text-base text-muted">{description}</p>}
            <ConfirmActions close={close} confirmLabel={confirmLabel} onConfirm={onConfirm} />
          </>
        )}
      </Dialog>
    </DialogTrigger>
  )
}

// The same confirmation, opened from code (e.g. a "Delete" menu item).
export function ConfirmDialog({
  isOpen,
  onOpenChange,
  title,
  description,
  confirmLabel = t("common.delete"),
  onConfirm
}: { isOpen: boolean; onOpenChange: (open: boolean) => void; title: string; description?: ReactNode; confirmLabel?: string; onConfirm: () => void }) {
  return (
    <Dialog title={title} isOpen={isOpen} onOpenChange={onOpenChange}>
      {(close) => (
        <>
          {description && <p className="text-base text-muted">{description}</p>}
          <ConfirmActions close={close} confirmLabel={confirmLabel} onConfirm={onConfirm} />
        </>
      )}
    </Dialog>
  )
}
